'use strict';
const icons={plate:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="3.5"/><path d="M2 4v6m-1-6v4q0 2 2 2V4M3 10v10M22 4v16m0-16q-4 4 0 8"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',pot:'<path d="M4 9h16v9a3 3 0 0 1-3 3H7a3 3 0 0 1-3-3V9ZM2 12h2m16 0h2M3 6h18M9 3h6M9 6V3m6 3V3"/>',file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.plate}</svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
let data,dayIndex=0;const content=document.querySelector('#content'),live=document.querySelector('#live');
function readStore(k){try{return JSON.parse(localStorage.getItem(k)||'[]')}catch{return []}}
let checked=new Set(readStore('atable-courses-v8')),done=new Set(readStore('atable-prep-v8'));
function readObj(k){try{const v=JSON.parse(localStorage.getItem(k)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}catch{return {}}}
let choice=readObj('atable-petitdej-v11');
function saveChoice(){try{localStorage.setItem('atable-petitdej-v11',JSON.stringify(choice))}catch{live.textContent='Votre choix ne pourra pas être conservé après fermeture.'}}
const breakfastOf=d=>d.breakfasts.find(b=>b.id===choice[d.name])||d.breakfasts[0]||null;
function mealsOf(d){const b=breakfastOf(d);return b&&b.id!==d.breakfasts[0].id?[{...d.meals[0],ingredients:b.ingredients,q:b.q,macros:b.macros,note:b.note},...d.meals.slice(1)]:d.meals}
function totalOf(meals){const t={P:0,L:0,G:0,kcal:0};meals.forEach(m=>['P','L','G','kcal'].forEach(k=>t[k]+=m.macros[k]));return t}
function save(k,set){try{localStorage.setItem(k,JSON.stringify([...set]))}catch{live.textContent='Vos coches ne pourront pas être conservées après fermeture.'}}
const n=x=>Number(x).toLocaleString('fr-FR',{maximumFractionDigits:1,minimumFractionDigits:1});
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function head(label,title,desc,ico){return `<div class="page-head"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p class="intro">${desc}</p></div><div class="head-art" aria-hidden="true">${icon(ico)}</div></div>`}
function notice(text){return `<div class="notice">${icon('info')}<span>${text}</span></div>`}
function menus(){const d=data.days[dayIndex],meals=mealsOf(d),tot=totalOf(meals),bf=breakfastOf(d),training=d.type==='training',targets=training?[120,65,175]:[125,60,80];
content.innerHTML=head('MES MENUS','À table, <em>l’esprit léger.</em>','Quatre journées pour bien manger et garder votre rythme.','plate')+`<div class="day-tabs" role="group" aria-label="Choisir une journée">${data.days.map((d,i)=>`<button class="day-tab" data-day="${i}" aria-pressed="${i===dayIndex}"><span>${d.type==='training'?'Jour actif':'Récupération'}</span><strong>${d.name}</strong></button>`).join('')}</div><div class="day-heading"><div><h2>${d.name}</h2><p>${training?'CrossFit supposé après 17 h':'Une journée pour récupérer'}</p></div><span class="pill">${meals.length} prises dans la journée</span></div><div class="macros-overview" aria-label="Apports estimés de la journée"><div class="metric"><div class="metric-top">ÉNERGIE</div><strong>${Math.round(tot.kcal).toLocaleString('fr-FR')}<small>kcal</small></strong><div class="metric-sub">Apport journalier estimé</div></div>${['P','L','G'].map((k,i)=>`<div class="metric ${k.toLowerCase()}"><div class="metric-top"><span class="metric-dot"></span>${['PROTÉINES','LIPIDES','GLUCIDES'][i]}</div><strong>${n(tot[k])}<small>g</small></strong><div class="metric-sub">${i===0?'Repère initial':'Cible du plan'} : ${targets[i]} g</div></div>`).join('')}</div>`+notice('<strong>Viandes et féculents : poids cuits.</strong> Viandes et féculents sans sauce ; pommes de terre épluchées et cuites à l’eau. Conserves égouttées. Huile dosée séparément.')+`<div class="section-label"><h3>Au fil de la journée</h3><span>1 personne · quantités validées</span></div><div class="meal-grid">${meals.map((m,i)=>`<article class="meal-card${i===0&&d.breakfasts.length>1?' has-choice':''}"><div class="meal-head"><span class="meal-number">${String(i+1).padStart(2,'0')}</span><div><h3>${m.name}</h3><small>${Math.round(m.macros.kcal)} kcal estimées${i===0&&d.breakfasts.length>1?' · au choix, même cible':''}</small></div></div>${i===0&&d.breakfasts.length>1?`<div class="bf-choice" role="group" aria-label="Choisir le petit déjeuner">${d.breakfasts.map(b=>`<button type="button" data-bf="${b.id}" aria-pressed="${b.id===bf.id}">${escape(b.label)}</button>`).join('')}</div>`:''}<ul class="ingredient-list">${m.ingredients.map(f=>`<li><span>${escape(f.name)}${f.state?`<small>${escape(f.state)}</small>`:''}</span><strong>${escape(f.amount)}</strong></li>`).join('')}</ul>${m.note?`<p class="meal-note">${escape(m.note)}</p>`:''}<div class="meal-macros" aria-label="Macronutriments du repas">${['P','L','G'].map((k,i)=>`<span class="macro-chip ${k.toLowerCase()}" title="${['Protéines','Lipides','Glucides'][i]}"><strong>${k}</strong> ${n(m.macros[k])} g</span>`).join('')}</div></article>`).join('')}</div><div class="details-group">${data.info.map(s=>`<details><summary>${s.title}</summary><div class="rich">${s.html}</div></details>`).join('')}</div>`;
content.querySelectorAll('[data-day]').forEach(b=>b.addEventListener('click',()=>{dayIndex=Number(b.dataset.day);menus();content.querySelector(`[data-day="${dayIndex}"]`).focus({preventScroll:true});live.textContent=data.days[dayIndex].name+' affiché';}));
content.querySelectorAll('[data-bf]').forEach(b=>b.addEventListener('click',()=>{choice[d.name]=b.dataset.bf;saveChoice();menus();content.querySelector(`[data-bf="${b.dataset.bf}"]`).focus({preventScroll:true});const t=totalOf(mealsOf(d));live.textContent=`Petit déjeuner ${breakfastOf(d).label} choisi. ${d.name} : ${Math.round(t.kcal)} kcal, protéines ${n(t.P)} g, lipides ${n(t.L)} g, glucides ${n(t.G)} g.`;}));}
function progressHtml(count,total,kind){return `<div class="progress-panel"><div class="progress-label"><strong id="progress-text">${count} sur ${total} ${kind==='courses'?'produits prêts':'étapes cochées'}</strong><small>${kind==='courses'?'Cochez ce que vous avez déjà ou ce que vous venez d’acheter.':'Avancez à votre rythme, une étape après l’autre.'}</small></div><div class="progress-track" role="progressbar" aria-label="Avancement" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${count}"><span style="width:${count/total*100}%"></span></div></div>`}
function updateProgress(count,total,label){document.querySelector('#progress-text').textContent=`${count} sur ${total} ${label}`;const bar=document.querySelector('[role=progressbar]');bar.setAttribute('aria-valuenow',count);bar.firstElementChild.style.width=count/total*100+'%';live.textContent=`${count} sur ${total} ${label}`;}
const r50=x=>Math.ceil(x/50)*50,gr=x=>Number(x.toFixed(1)).toLocaleString('fr-FR');
const shopRules={oeuf:v=>{const k=Math.round(v/50);return [`${k} œufs entiers`,`${k} œufs, aucun blanc séparé`]},
poulet:v=>[`${gr(v)} g cuits`,`Prévoir environ ${r50(v*1.6)} g crus pour avoir une marge de cuisson ; peser le résultat et réserver le surplus`],
fromage_blanc:v=>[`${gr(v)} g`,`Au moins ${gr(v)} g, selon le conditionnement disponible`],
sardines:v=>[`${gr(v)} g égouttés`,`Une réserve totalisant au moins ${gr(v)} g égouttés`],
biscotte_seigle:v=>{const k=Math.round(v/10);return [k?`${k} biscotte${k>1?'s':''}`:'Aucune avec vos choix',null]},
galette:v=>{const k=Math.round(v/7);return [k?`${k} galette${k>1?'s':''}`:'Aucune avec vos choix',null]},
tomate:v=>[`${gr(v)} g`,`Environ ${gr(v+50)} g pour la marge de préparation`],concombre:v=>[`${gr(v)} g`,`Environ ${gr(v+50)} g`],
pomme:v=>[`${gr(v)} g sans trognon`,`Environ ${r50(v*1.28)} g entières`],poire:v=>[`${gr(v)} g sans trognon`,`Environ ${r50(v*1.23)} g entières`],
huile:v=>[`${gr(v)} g`,`${gr(v)} g disponibles ; ce total inclut toutes les prises`]};
function needs(chosen){const t={};data.days.forEach(d=>(chosen?mealsOf(d):d.meals).forEach(m=>Object.entries(m.q).forEach(([k,v])=>t[k]=(t[k]||0)+v)));return t}
function shopItem(f,base,cur){if(!f.key||!shopRules[f.key]||Math.abs((cur[f.key]||0)-(base[f.key]||0))<.05)return {...f,changed:false};const [q,note]=shopRules[f.key](cur[f.key]||0);return {...f,quantity:q,note:note??f.note,changed:true}}
function courses(){const base=needs(false),cur=needs(true),picked=data.days.filter(d=>d.breakfasts.length>1).map(d=>`${d.name} : <strong>${escape(breakfastOf(d).label.toLowerCase())}</strong>`).join(' · ');const total=data.shopping.reduce((n,g)=>n+g.items.length,0);content.innerHTML=head('MES COURSES','Le nécessaire, <em>rien de plus.</em>','Votre liste pour les quatre journées. Commencez par regarder dans vos placards.','bag')+progressHtml(checked.size,total,'courses')+`<div class="toolbar"><span class="metric-sub">Les coches sont conservées sur cet appareil.</span><a class="outline-button" href="downloads/Liste-de-courses-4-jours.pdf" download>${icon('file')} Télécharger la liste</a></div>`+notice('Les quantités ci-dessous sont les <strong>besoins totaux</strong> : déduisez votre stock. Les poids crus ou secs à acheter sont des estimations avec marge ; servez les portions cuites du menu.')+notice(`<strong>Petits déjeuners pris en compte</strong> (à changer dans <a href="#menus">Mes menus</a>) : ${picked}.`)+`<div class="shopping-grid">${data.shopping.map(g=>`<section class="shopping-group"><h3>${g.title}</h3>${g.items.map(f=>shopItem(f,base,cur)).map(f=>`<label class="shop-row"><input type="checkbox" data-shop="${f.id}" ${checked.has(f.id)?'checked':''}><span class="shop-copy"><span class="shop-title"><strong>${escape(f.name)}</strong>${f.changed?'<span class="shop-tag">selon vos petits déjeuners</span>':''}</span><span class="shop-quantity">${escape(f.quantity)}</span><small>${escape(f.note)}</small></span></label>`).join('')}</section>`).join('')}</div><div class="section-label"><span>16 portions de légumes de 100 g · Une seule variété par repas solide.</span></div>`;
content.querySelectorAll('[data-shop]').forEach(el=>el.addEventListener('change',()=>{el.checked?checked.add(el.dataset.shop):checked.delete(el.dataset.shop);save('atable-courses-v8',checked);updateProgress(checked.size,total,'produits prêts')}));}
function preparation(){content.innerHTML=head('MA PRÉPARATION','Un peu de cuisine.<br><em>Quatre jours plus simples.</em>','Une session de préparation, puis quelques finitions au quotidien.','pot')+progressHtml(done.size,data.steps.length,'prep')+`<div class="toolbar"><span class="metric-sub">Exemple d’ordre : entraînement 1, repos 1, entraînement 2, repos 2.</span><a class="outline-button" href="downloads/Batch-cooking-4-jours.pdf" download>${icon('file')} Le guide en PDF</a></div><div class="prep-layout"><div class="prep-list">${data.steps.map((s,i)=>`<details ${i===0?'open':''}><summary><span class="step-num">${String(i+1).padStart(2,'0')}</span><span>${s.title}</span></summary><div class="rich">${s.html}</div><label class="step-done"><input type="checkbox" data-step="${i}" ${done.has(i)?'checked':''}> Étape terminée</label></details>`).join('')}</div><aside class="prep-note"><span class="eyebrow">VOTRE TEMPS EN CUISINE</span><h3>Préparer aujourd’hui.<br>Souffler demain.</h3><strong>1 h 30 à 2 h</strong><small>pour la session principale</small><hr><strong>5 à 10 min</strong><small>de finitions chaque jour</small><hr><p>Préparez la balance, les boîtes et les étiquettes avant de commencer.</p><p><strong style="font:600 12px 'DM Sans',sans-serif">Le froid compte aussi.</strong><br>Suivez les durées de conservation indiquées, particulièrement pour le riz.</p></aside></div>`;
content.querySelectorAll('[data-step]').forEach(el=>el.addEventListener('change',()=>{const i=Number(el.dataset.step);el.checked?done.add(i):done.delete(i);save('atable-prep-v8',done);updateProgress(done.size,data.steps.length,'étapes cochées')}));}
function route(){if(!data)return;const view=location.hash.slice(1)||'menus';const selected=['menus','courses','preparation'].includes(view)?view:'menus';document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===selected);a.dataset.view===selected?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')});document.querySelector('#breadcrumb').textContent={menus:'Menus',courses:'Courses',preparation:'Préparation'}[selected];({menus,courses,preparation})[selected]();document.title={menus:'Mes menus',courses:'Mes courses',preparation:'Ma préparation'}[selected]+' — À table';}
window.addEventListener('hashchange',()=>{route();window.scrollTo({top:0,behavior:'instant'})});
const docs=document.querySelector('#docs');document.querySelector('#open-docs').addEventListener('click',()=>docs.showModal());document.querySelector('#close-docs').addEventListener('click',()=>docs.close());docs.addEventListener('click',e=>{if(e.target===docs){const r=docs.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)docs.close()}});
fetch('data.json?v=20261114-v11', {cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('Chargement');return r.json()}).then(d=>{data=d;route()}).catch(()=>{content.innerHTML='<h1>Le carnet n’a pas pu se charger.</h1><p>Rechargez la page ou retrouvez les PDF avec le bouton d’impression.</p>'});

document.querySelector(".skip").addEventListener("click",e=>{e.preventDefault();document.querySelector("#main").focus();document.querySelector("#main").scrollIntoView()});
